function showHow(){if(mode==='apartment'){showHomeHelp();return;}if(mode==='driving')paused=true;modal(`<button class="modal-close" data-close aria-label="Close">×</button><h2 id="dialogTitle">DRIVE THE NIGHT.</h2><p>Follow the mint arrows to a pickup. Stop inside the ring to let a passenger in. Then drive to their blue hideout ring and stop to collect the fare.</p><div class="instruction"><span>Pickups</span><b>GREEN easy · GOLD risky · RED hot</b></div><div class="instruction"><span>Keep your streak</span><b>DELIVERIES BOOST YOUR MULTIPLIER</b></div><div class="instruction"><span>Save your earnings</span><b>STOP AT THE GARAGE. BANK YOUR HAUL.</b></div><div class="desktop-only"><div class="instruction"><span>Drive / reverse</span><b>WASD / ARROW KEYS</b></div><div class="instruction"><span>Handbrake drift / nitro</span><b>SPACE / SHIFT</b></div><div class="instruction"><span>Camera / garage route</span><b>C / TAB</b></div><div class="instruction"><span>Bank haul / recover car</span><b>E / R</b></div></div><div class="mobile-only"><p>Hold GAS and steer with LEFT / RIGHT. BRAKE slows you down, then reverses. Hold DRIFT for tight corners and NITRO for a burst of speed.</p></div><p>Hot pickups bring police. Break their line of sight to lose your stars. Deliveries add 40 seconds. Crashing or running out of time loses your unbanked haul.</p><button class="primary" data-close>LET’S DRIVE <span>↗</span></button>`);}
function driverThumbnail(item){
 const key='driver:'+item.id;if(carThumbnails.has(key))return carThumbnails.get(key);const studio=new THREE.Scene();studio.background=new THREE.Color('#17263b');studio.add(new THREE.HemisphereLight('#e0efff','#233448',3));const light=new THREE.DirectionalLight('#ffe7bf',4);light.position.set(-3,6,5);studio.add(light);
 const asset=templates[item.model].scene.clone(true),rig=new THREE.Group();asset.updateMatrixWorld(true);const box=new THREE.Box3().setFromObject(asset),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3()),scale=2/size.y;asset.scale.setScalar(scale);asset.position.set(-center.x*scale,-box.min.y*scale,-center.z*scale);rig.add(asset);rig.rotation.y=.25;studio.add(rig);const eye=new THREE.PerspectiveCamera(34,2,.1,30);eye.position.set(2,1.65,4.6);eye.lookAt(0,1,0);
 const target=new THREE.WebGLRenderTarget(480,240,{samples:2}),previous=renderer.getRenderTarget(),pixels=new Uint8Array(480*240*4);target.texture.colorSpace=THREE.SRGBColorSpace;let url='';try{renderer.setRenderTarget(target);renderer.render(studio,eye);renderer.readRenderTargetPixels(target,0,0,480,240,pixels);const canvas=document.createElement('canvas');canvas.width=480;canvas.height=240;const ctx=canvas.getContext('2d'),img=ctx.createImageData(480,240);for(let y=0;y<240;y++)img.data.set(pixels.subarray(y*1920,(y+1)*1920),(239-y)*1920);ctx.putImageData(img,0,0);url=canvas.toDataURL('image/png');}finally{renderer.setRenderTarget(previous);target.dispose();}carThumbnails.set(key,url);return url;
}
function showGarage(options={}){if(!ready||collectionUI?.isBusy())return;paused=true;clearControls();if(!collectionUI)collectionUI=createCollectionUI({profile:()=>profile,cars:CARS,paints:PAINTS,wallet:burnWallet,modal,save:saveProfile,home:()=>phoneUI?.isOpen()?phoneUI.open('home'):mode==='garage'?(closeModal(),refreshGarageUI()):returnHome(),homeLabel:()=>phoneUI?.isOpen()?'BACK TO PHONE':mode==='garage'?'BACK TO GARAGE':'BACK TO APARTMENT',reconcile:()=>{reconcileCollection();apartment.setCharacter(templates[activeDriver().model]);if(mode==='apartment')replacePlayer();if(mode==='garage')refreshGarageUI();refreshMenu();},buy:id=>buyCar(profile,id),thumbnail:item=>item.kind==='driver'?driverThumbnail(item):item.kind==='skin'?carThumbnail(CARS[profile.selected],item):carThumbnail(item),equip:item=>{const kind=item.kind||'car';if(kind==='driver'){profile.collection.driver=item.id;apartment.setCharacter(templates[activeDriver().model]);}else if(kind==='skin')profile.collection.skin=item.id;else profile.selected=item.id;if(mode==='apartment')replacePlayer();else if(kind==='skin'&&mode==='driving'){world.remove(playerView.group);disposeVehicle(playerView);playerView=carView(player.config.model,player.config.scale,PAINTS[profile.paint],activeSkin());animateCar(playerView,player,0);}refreshMenu();if(mode==='garage'){if(kind==='car')garageCarId=item.id;refreshGarageUI();}}});collectionUI.open(options);}

