function startRun(){if(!ready||collectionUI?.isBusy())return;reconcileCollection();if(profile.tutorialStep<2){returnHome();return;}closeModal();initAudio();profile.checkpoint=null;resetRun();mode='driving';if(profile.tutorialStep<6){profile.tutorialStep=3;pickupLock='diner';}showDrivingUI();refreshRoute();updateHUD();saveProfile();toast(touch?'Hold GAS. Follow the arrows to your first fare.':'W to accelerate. Follow the arrows to your first fare.','good',4);sound(250,.2,'triangle',.05,330);}
function resumeRun(){if(collectionUI?.isBusy())return;reconcileCollection();if(burnWallet.state().live&&BURN_CARS[profile.checkpoint?.carId]&&!profile.unlocked.includes(profile.checkpoint.carId)){toast('Connect your wallet in the collection to resume this ride.','good',4);showGarage();return;}const saved=restoreShift(profile.checkpoint,profile);if(!saved){profile.checkpoint=null;startRun();return;}closeModal();initAudio();cleanupRun();if(playerView){world.remove(playerView.group);disposeVehicle(playerView);}player=saved.car;run=saved.run;playerView=carView(player.config.model,player.config.scale,PAINTS[profile.paint],activeSkin());animateCar(playerView,player,0);for(const p of pickups){p.job=saved.jobs.find(j=>j.stopId===p.stop.id);p.index=Number(p.job.id.split('-').at(-1));if(p.job.picked)p.actor.onboard();else p.actor.wait();}({bankRoute,pickupLock,targetLock,mapWaypoint}=saved.locks);mode='driving';pickupProgress=0;pickupKey='';damageCooldown=.4;copSpawnTimer=0;roadblockTimer=10;cameraHeading=player.heading;cameraTarget.set(player.x,0,player.z);cameraPosition.set(player.x-12,16,player.z+14);showDrivingUI();stopActivities(0);refreshRoute();updateHUD();saveProfile();toast('SHIFT RESUMED. YOUR HAUL IS STILL ON BOARD.','good',3);}
function returnHome(){if(!ready||collectionUI?.isBusy())return;$('garageUI').classList.add('hidden');if(mode==='driving')saveProfile();closeModal();mode='apartment';['menu','bottomBar','carPlaque','hud'].forEach(id=>$(id).classList.add('hidden'));$('topbar').classList.remove('hidden');$('homeUI').classList.remove('hidden');arrows.count=0;apartment.setPosition(profile.home);apartment.resize(innerWidth,innerHeight);refreshHomeCamera();updateHomeUI();saveProfile();}
function returnMenu(){returnHome();}
function advanceTutorial(step){if(step>profile.tutorialStep&&profile.tutorialStep<6){profile.tutorialStep=step;saveProfile();if(mode==='apartment')updateHomeUI();}}
function updateHomeUI(){const step=profile.tutorialStep,lessons=[['GET YOUR BEARINGS',touch?'Tap the floor to walk. Tap furniture to use it.':'Click the floor to walk, or use WASD. Click furniture to use it.'],['CHECK YOUR LAPTOP','Click your bedroom laptop, or use Phone → Home.'],['YOUR RIDE IS DOWNSTAIRS','Use the front door in the entry hall to begin your first shift.']];const lesson=lessons[step]||[profile.checkpoint?'A SHIFT IS WAITING':'MAKE YOURSELF AT HOME',profile.checkpoint?'Your passengers, timer, and unbanked haul are saved. Use the door to get back to it.':'Watch TV, make coffee, shower, or rest. Your ride can wait.'];$('homeStep').textContent=step<6?'FIRST NIGHT / '+(step+1)+' OF 6':'APARTMENT 04 / YOUR HOME';$('homeTaskTitle').textContent=lesson[0];$('homeTaskBody').textContent=lesson[1];$('homeStepFill').style.width=(step/6*100)+'%';if(step>=6){const quest=phoneQuests(phoneState()).find(q=>q.tracked);if(quest){$('homeStep').textContent=quest.complete?'QUEST COMPLETE':'TRACKED QUEST';$('homeTaskTitle').textContent=quest.name;$('homeTaskBody').textContent=quest.complete?'Open your phone to choose your next quest.':quest.next+' · '+quest.value.toLocaleString()+' / '+quest.total.toLocaleString();$('homeStepFill').style.width=(quest.value/quest.total*100)+'%';}}$('homeCredits').textContent=profile.credits.toLocaleString()+' CR';$('homeBest').textContent=profile.best.toLocaleString();$('homeResume').classList.toggle('hidden',!profile.checkpoint);$('homeSave').textContent=storageAvailable?'PROGRESS SAVED':'SAVING UNAVAILABLE';}
function showHomeHelp(){paused=true;clearControls();modal(`<button class="modal-close" data-close aria-label="Close apartment guide">×</button><h2 id="dialogTitle">YOUR PLACE. YOUR PACE.</h2><p>Walk with WASD, arrow keys, or the direction buttons on your phone. Get close to a glowing marker, then press E or tap the action button. Click furniture to walk over and use it. The camera follows you. Press C for the floor plan; use + / − to zoom. Press F or the full-screen button to fill your display. Explore the kitchen, living room, bedroom, bathroom, and entry hall.</p><div class="instruction"><span>Laptop</span><b>YOUR FIRST JOB &amp; DISPATCH</b></div><div class="instruction"><span>Wardrobe</span><b>RIDES, SKINS &amp; DRIVERS</b></div><div class="instruction"><span>Bedside</span><b>SAVE YOUR PROGRESS</b></div><div class="instruction"><span>Entry door</span><b>START OR RESUME A SHIFT</b></div><p>Sit on the sofa to watch TV, make coffee in the kitchen, shower, or rest in bed. Press E or move to stop an activity. Open your phone with P to check quests, use home activities, and manage your garage. Your progress saves automatically on this browser. You can also save an unfinished shift from the driving pause menu and return home.</p><button class="primary" data-close>BACK TO MY APARTMENT</button>`);}
function leaveApartment(){if(profile.tutorialStep<2){updateHomeUI();return;}if(profile.checkpoint)resumeRun();else startRun();}
function interactHome(id=null){if(mode!=='apartment'||paused)return;if(apartment.activity){apartment.interact(apartment.activity.id);saveProfile();return;}const spot=typeof id==='string'&&apartment.canInteract(id)?HOME_SPOTS.find(h=>h.id===id):apartment.nearest();if(!spot)return;initAudio();if(spot.id==='laptop'){advanceTutorial(2);paused=true;clearControls();modal(`<button class="modal-close" data-close aria-label="Close dispatch">×</button><div class="result-kicker">LAST EXIT / DISPATCH</div><h2 id="dialogTitle">YOU’RE ON THE ROSTER.</h2><p>${profile.tutorialStep<3?'First job: a pickup at the 24-hour diner. Your ride is waiting downstairs.':'Your dispatch board is in the car. Choose a pickup, deliver your passengers, and bring the haul home.'}</p><div class="instruction"><span>Pick up</span><b>FOLLOW THE MINT ARROWS. STOP IN THE RING.</b></div><div class="instruction"><span>Drop off</span><b>DRIVE THE PASSENGER TO THE BLUE HIDEOUT.</b></div><div class="instruction"><span>Keep the money</span><b>RETURN TO LAST EXIT. BANK YOUR HAUL.</b></div><p>Start with five minutes. A pickup adds 10 seconds and a delivery adds 40. There’s no clock running while you’re home.</p><button class="primary" data-close>GOT IT. FIND THE DOOR.</button>`);}else if(spot.id==='garage')enterGarage();else if(spot.id==='wardrobe')showGarage();else if(spot.id==='bed'){const message=apartment.interact('bed');saveProfile();toast(storageAvailable?message:'RESTING. SAVING IS UNAVAILABLE.','good');}else if(spot.id==='door')leaveApartment();else{const message=apartment.interact(spot.id);if(message){toast(message,'good');saveProfile();}}}
function finish(success,reason=''){if(mode!=='driving'||!settleRun(run,profile,success))return;mode=success?'banked':'busted';profile.checkpoint=null;if(profile.tutorialStep<6)profile.tutorialStep=success&&run.deliveries>0?6:3;saveProfile();clearControls();jingle(success);$('bankBtn').classList.add('hidden');$('stopProgress').classList.add('hidden');const lost=Math.floor(run.haul+run.style);modal(`<div class="result-kicker">${success?'BACK IN ONE PIECE':'THE NIGHT CAUGHT UP'}</div><h2 id="dialogTitle">${success?'MONEY IN THE GARAGE.':reason||'BUSTED.'}</h2><div class="result-score">${run.total.toLocaleString()}</div><div class="score-label">CREDITS BANKED${success?'':' · '+lost.toLocaleString()+' LOST'}</div><div class="result-stats"><div><small>PASSENGERS SAVED</small><strong>${run.deliveries}</strong></div><div><small>STREAK MULTIPLIER</small><strong>×${run.combo.toFixed(2)}</strong></div><div><small>STYLE BONUS</small><strong>${Math.floor(run.style)}</strong></div></div><p>${success?'That haul is safe. Upgrade your ride or go back for another shift.':'Break line of sight to lose the police. Bank early if your car or your clock is running low.'}</p><button id="againBtn" class="primary">BACK TO MY APARTMENT <span>↗</span></button><div class="modal-secondary"><button id="resultGarage" class="small-btn">GARAGE · ${profile.credits.toLocaleString()} CR</button><button id="resultMenu" class="small-btn">HOME</button></div><p class="note">Arcade credits only. Progress is saved on this device.</p>`);$('againBtn').onclick=returnHome;$('resultGarage').onclick=()=>{returnMenu();showGarage();};$('resultMenu').onclick=returnMenu;refreshMenu();}

