 if(mode==='garage'&&!paused&&['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyE'].includes(e.code)){e.preventDefault();if(e.code==='KeyE'&&!keys.KeyE)interactGarage();keys[e.code]=true;return;}
