register({name:'read_getaway_state',title:'Read Getaway game',description:'Read the current solo driving run, car, passengers, route, wanted level, and arcade credits.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('No parameters accepted.');return{mode,ready,paused,car:mode==='driving'?player.config.id:profile.selected,credits:profile.credits,haul:Math.floor(run.haul+run.style),passengers:run.passengers.length,wanted:run.wanted,secondsLeft:Math.ceil(run.time),target:target?.name,livePayouts:false,tutorialStep:profile.tutorialStep,savedShift:!!profile.checkpoint};}});
